        let abandoned_count =
            sync::io::count_by_status(&connection, &slug, OutboxStatus::Abandoned)?;

        let last_error = sync::io::last_error_for_project(&connection, &slug)?;
        let last_pull_at = sync::io::read_sync_cursor(&connection, &slug)?.last_pull_at;

        Ok(SyncStatusReport {
            adapter_id,
            sync_connection_id,
            last_pull_at,
            pending_count,
            failed_count,
            abandoned_count,
            last_error,
        })
    })
